        return "unknown";
    } else if (type.isAllType()) {
        return "all";
    } else if (type.isNullType()) {
        return "null";
    } else if (type.isVoidType()) {
        return "void";
    } else if (type.isBooleanValueType()) {
        return "boolean";
    } else if (type.isNumberValueType()) {
        return "number";
    } else if (type.isStringValueType()) {
        return "string";
    } else {
        return "object";
    }
}

